"use client";

import { useState } from "react";

export default function Home() {
  const [message, setMessage] = useState("Hello from React");

  return (
    <main style={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: "100vh" }}>
      <div style={{ border: "1px solid #ddd", borderRadius: "12px", padding: "1.5rem", textAlign: "center" }}>
        <h1>Simple UI</h1>
        <p>{message}</p>
        <button onClick={() => setMessage("This block updated!")}>Show text</button>
      </div>
    </main>
  );
}
